class Solution:
    def resultArray(self, nums: list[int], k: int, queries: list[list[int]]) -> list[int]:
        nums = [x % k for x in nums]
        n = len(nums)
        ans = []
        for q in queries:
            idx, val, start, x = q[0], q[1] % k, q[2], q[3]
            nums[idx] = val
            prod = 1
            cnt = 0
            for i in range(start, n):
                prod = (prod * nums[i]) % k
                if prod == x:
                    cnt += 1
            ans.append(cnt)
        return ans

#include <vector>

using namespace std;

class Solution {
public:
    vector<int> resultArray(vector<int>& nums, int k, vector<vector<int>>& queries) {
        for (int& x : nums) x %= k;
        int n = nums.size();
        vector<int> ans;
        for (const auto& q : queries) {
            int idx = q[0], val = q[1] % k, start = q[2], x = q[3];
            nums[idx] = val;
            int prod = 1, cnt = 0;
            for (int i = start; i < n; ++i) {
                prod = (prod * nums[i]) % k;
                if (prod == x) cnt++;
            }
            ans.push_back(cnt);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] resultArray(int[] nums, int k, int[][] queries) {
        for (int i = 0; i < nums.length; i++) nums[i] %= k;
        int n = nums.length;
        int[] ans = new int[queries.length];
        for (int j = 0; j < queries.length; j++) {
            int idx = queries[j][0], val = queries[j][1] % k, start = queries[j][2], x = queries[j][3];
            nums[idx] = val;
            int prod = 1, cnt = 0;
            for (int i = start; i < n; i++) {
                prod = (prod * nums[i]) % k;
                if (prod == x) cnt++;
            }
            ans[j] = cnt;
        }
        return ans;
    }
}

var resultArray = function(nums, k, queries) {
