    const n = nums.length;
    const ans = [];
    for (const q of queries) {
        const idx = q[0], val = q[1] % k, start = q[2], x = q[3];
        nums[idx] = val;
        let prod = 1, cnt = 0;
        for (let i = start; i < n; i++) {
            prod = (prod * nums[i]) % k;
            if (prod === x) cnt++;
